//   Read Binary File → Spreadsheet File (xlsx) → (este nodo).
// Cada item de salida = UNA fila de proveedor con las columnas del Excel.
const rows = [
  { row_number: 2, ID_PROVEEDOR: 10248, NOMBRE_PROVEEDOR: 'Antel',       TELEFONO_MOVIL: '', OTRO_TELEFONO: '', CORREO_ELECTRONICO: '', DIRECCION: '', OTRA_INFO: '', ESTADO: 1 },
  { row_number: 3, ID_PROVEEDOR: 5244,  NOMBRE_PROVEEDOR: 'BRACKETS UP', TELEFONO_MOVIL: '', OTRO_TELEFONO: '', CORREO_ELECTRONICO: '', DIRECCION: '', OTRA_INFO: '', ESTADO: 1 }
];

return rows.map((r) => ({ json: r }));

// Junta los ids de todos los proveedores upserted en un solo objeto resumen.
const items = $input.all();
const ids = items.map((i) => i.json && i.json.id).filter(Boolean);

return [{ json: { count: ids.length, provider_ids: ids } }];
